INSERT INTO projects ("id", "title", "year", "context", "problem", "objectives", "role", "methodology", "solutions", "results", "tags", "link", "link_label", "logo_url", "image_url", "published", "order", "created_date", "updated_date") VALUES ('6af19f7ee5e2ef2c91868c28', 'Programmes de serious games — collectivités et secteur public', 'Serious game', 'Projets menés pour la Région Bretagne, la Région Grand Est, l''ARS, le Port de Nantes-Saint-Nazaire, la FNTP et Astek, chez Ludicius Interactive (2024-2026).', '', '', 'Chef de projet : cadrage, recueil des besoins, gestion et priorisation du backlog, suivi des livrables et gestion des retours utilisateurs.', 'Cadrage, spécifications, planification, comités de suivi et recette.', 'Coordination des développeurs, DevOps, graphistes, UX designer et concepteurs mobilisés sur les projets.', '', '["Serious game", "Secteur public", "Ludicius"]', '', '', '', '', 1, 3, '2026-11-09T10:25:02.564000', '2026-11-09T10:25:02.564000');
INSERT INTO projects ("id", "title", "year", "context", "problem", "objectives", "role", "methodology", "solutions", "results", "tags", "link", "link_label", "logo_url", "image_url", "published", "order", "created_date", "updated_date") VALUES ('6af19f7ee5e2ef2c91868c27', 'Serious game — SNCF et La Poste', 'Serious game', 'Dispositifs de formation interactive conçus pour SNCF et La Poste, chez Ludicius Interactive (2024-2026).', '', '', 'Chef de projet : cadrage, spécifications fonctionnelles, backlog, planification et recette.', 'Recueil des besoins, spécifications, itérations avec le client, recette fonctionnelle.', 'Pilotage d''une équipe pluridisciplinaire (développement, graphisme, UX, conception).', '', '["Serious game", "Formation", "Ludicius"]', '', '', '', '', 1, 2, '2026-11-09T10:25:02.564000', '2026-11-09T10:25:02.564000');
INSERT INTO projects ("id", "title", "year", "context", "problem", "objectives", "role", "methodology", "solutions", "results", "tags", "link", "link_label", "logo_url", "image_url", "published", "order", "created_date", "updated_date") VALUES ('6af19f7ee5e2ef2c91868c26', 'Serious game — Bpifrance', 'Serious game', 'Conception d''un jeu sérieux pour Bpifrance, chez Ludicius Interactive (2024-2026).', '', '', 'Chef de projet : cadrage, recueil des besoins, spécifications fonctionnelles, gestion et priorisation du backlog, planification, suivi des livrables et recette.', 'Cadrage fonctionnel, spécifications, backlog priorisé, suivi des livrables et des retours utilisateurs, recette.', 'Coordination d''une équipe de 13 personnes : développeurs, DevOps, graphistes, UX designer et concepteurs.', '', '["Serious game", "Ludicius", "Bpifrance"]', '', '', '', '', 1, 1, '2026-11-09T10:25:02.564000', '2026-11-09T12:16:11.131000');
INSERT INTO experiences ("id", "company", "role", "start", "end", "context", "role_team", "project", "missions", "tags", "published", "order", "created_date", "updated_date") VALUES ('6af19ecdf747c2cfbdac7d5d', 'Digital Slaves', 'Dirigeant et chef de projet – Ingénierie événementielle', 'févr. 2003', 'oct. 2019', 'CDI · Clients : LVMH, La Poste, Orange, UBS, Sephora, Reebok, Crédit Mutuel, Nokia, Microsoft, Calvin Klein, Toyota, Uniqlo, BNP, Altarea Cogedim', 'Dirigeant et chef de projet encadrant une équipe pluridisciplinaire de 5 à 10 collaborateurs (développeurs, graphistes et concepteurs).', 'Direction et pilotage d''une structure spécialisée en ingénierie événementielle. Conception de solutions technologiques innovantes pour des clients grands comptes, du besoin client jusqu''à la livraison finale.', '["Pilotage global de l''entreprise incluant les aspects financiers, commerciaux, techniques et opérationnels.", "Gestion active du backlog, priorisation des fonctionnalités et planification des étapes de développement.", "Supervision du suivi des livrables et coordination des phases de recette pour garantir la conformité aux exigences des clients.", "Développement technique d''applications interactives et de systèmes d''ingénierie événementielle.", "Encadrement et animation de l''équipe pour assurer la cohérence entre les créations graphiques et les développements techniques."]', '["Gestion de projet", "Leadership d''équipe", "Gestion financière", "Développement commercial", "VVVV", "HLSL", "Arduino", ".NET C#", "Programmation 2D/3D avec DirectX"]', 1, 5, '2026-11-09T10:22:05.462000', '2026-11-09T10:22:05.462000');
INSERT INTO experiences ("id", "company", "role", "start", "end", "context", "role_team", "project", "missions", "tags", "published", "order", "created_date", "updated_date") VALUES ('6af19ecdf747c2cfbdac7d5c', 'Indépendant', 'Consultant - IT', 'oct. 2019', 'sept. 2022', 'Mission indépendante', 'Consultant IT indépendant en charge de la conception et de la réalisation de solutions techniques personnalisées pour divers clients.', 'Accompagnement dans la transformation numérique et le développement d''outils logiciels sur mesure pour répondre aux besoins spécifiques des entreprises.', '["Rédaction de spécifications fonctionnelles et techniques détaillées en amont des développements.", "Conception et intégration de solutions logicielles adaptées aux architectures existantes des clients.", "Développement de fonctionnalités critiques et maintien de la qualité du code produit.", "Assistance aux choix technologiques et conseil stratégique auprès des parties prenantes."]', '["Conseil en informatique", "Spécifications fonctionnelles", "Cahiers des charges", "Développement logiciel", "Intégration de systèmes"]', 1, 4, '2026-11-09T10:22:05.462000', '2026-11-09T10:22:05.462000');
INSERT INTO experiences ("id", "company", "role", "start", "end", "context", "role_team", "project", "missions", "tags", "published", "order", "created_date", "updated_date") VALUES ('6af19ecdf747c2cfbdac7d5b', 'ADOC Solutions', 'Chef de projet fonctionnel et technique – GED', 'oct. 2022', 'oct. 2023', 'CDI · Clients : Dalkia, BnF, BPCE, Verre Solution, Mairie de Bourges', 'Chef de projet fonctionnel et technique encadrant une équipe pluridisciplinaire de 7 collaborateurs (développeurs, ingénieurs DevOps et techniciens).', 'Pilotage de projets de Gestion Électronique de Documents (GED) pour des clients grands comptes (secteurs bancaire, public et industriel). L''objectif était de digitaliser et d''optimiser la gestion documentaire métier à travers des solutions robustes et sécurisées.', '["Cadrage des besoins clients et traduction en spécifications fonctionnelles détaillées.", "Gestion active du backlog produit : priorisation des tickets, planification des sprints et suivi rigoureux des livrables.", "Intégration, modélisation et optimisation des processus métiers critiques (comptabilité, ressources humaines, logistique).", "Supervision des phases de recette utilisateur et coordination des retours pour garantir la conformité aux besoins exprimés.", "Audit des infrastructures réseaux et pilotage du déploiement des architectures de bases de données.", "Administration courante des serveurs de données pour assurer la haute disponibilité des services."]', '["Gestion de projet", "Spécifications fonctionnelles", "Méthodologie Agile", "Gestion de Backlog", "Modélisation de processus métier", "Audit réseau", "Administration de base de données", "MSSQL", "PostgreSQL", "DevOps"]', 1, 3, '2026-11-09T10:22:05.462000', '2026-11-09T10:22:05.462000');
INSERT INTO experiences ("id", "company", "role", "start", "end", "context", "role_team", "project", "missions", "tags", "published", "order", "created_date", "updated_date") VALUES ('6af19ecdf747c2cfbdac7d5a', 'Indépendant', 'Consultant - IT', 'oct. 2023', 'août 2024', 'Mission indépendante', 'Consultant IT indépendant intervenant en tant qu''expert technique autonome sur des projets de développement informatique.', 'Conception, intégration et développement de solutions logicielles sur mesure visant à optimiser les processus techniques et fonctionnels des systèmes d''information.', '["Analyse et rédaction détaillée des spécifications fonctionnelles et techniques pour assurer l''adéquation avec les besoins métiers.", "Conception et développement de composants techniques robustes au sein des infrastructures existantes.", "Intégration de solutions logicielles et déploiement de fonctionnalités critiques dans des environnements techniques variés.", "Suivi de la qualité du code et respect des standards de développement tout au long du cycle de vie du projet."]', '["Spécifications fonctionnelles", "Cahiers des charges", "Développement logiciel", "Intégration système", "Ingénierie logicielle"]', 1, 2, '2026-11-09T10:22:05.462000', '2026-11-09T10:22:05.462000');
INSERT INTO experiences ("id", "company", "role", "start", "end", "context", "role_team", "project", "missions", "tags", "published", "order", "created_date", "updated_date") VALUES ('6af19ecdf747c2cfbdac7d59', 'Ludicius Interactive', 'Chef de projet – Jeux vidéo et serious games', 'sept. 2024', 'sept. 2026', 'CDI · Clients : Bpifrance, Région Bretagne, Région Grand Est, La Poste, SNCF, Port de Nantes-Saint-Nazaire, ARS, Astek, FNTP', 'Chef de projet au sein d''une équipe pluridisciplinaire de 13 collaborateurs composée de développeurs, DevOps, graphistes, UX designers et concepteurs.', 'Conception et réalisation de jeux vidéo et de serious games personnalisés pour des institutions publiques et de grandes entreprises (Bpifrance, Région Bretagne, Région Grand Est, La Poste, SNCF, Port de Nantes Saint-Nazaire, ARS, Astek, FNTP).', '["Cadrage stratégique des projets et recueil des besoins clients pour aligner les solutions de gamification aux objectifs métiers.", "Rédaction des spécifications fonctionnelles détaillées.", "Gestion et priorisation du backlog produit pour assurer la livraison de fonctionnalités à haute valeur ajoutée.", "Planification des sprints et suivi rigoureux des livrables pour respecter les jalons contractuels.", "Coordination des équipes techniques et créatives pour garantir la cohérence artistique et technique.", "Gestion des retours utilisateurs, animation des séances de recette et pilotage des phases de correction.", "Intégration de solutions IA et d''automatisation pour la productivité interne."]', '["Gestion de projet", "Serious games", "Gestion de Backlog", "Product Ownership", "Méthodologie Agile", "Gestion des spécifications techniques", "Gestion des parties prenantes", "Conception UX", "Coordination DevOps", "Claude / Claude Code", "N8N", "Processus d''automatisation IA"]', 1, 1, '2026-11-09T10:22:05.462000', '2026-11-09T10:22:05.462000');
INSERT INTO site_settings ("id", "name", "initials", "role", "tagline", "intro", "location", "email", "linkedin", "cv_url", "created_date", "updated_date") VALUES ('6af19d7ebb3afd2716dc9380', 'Anthony Gouvrillon', 'AG', 'Chef de projet IT', 'Faire avancer les projets. Donner du sens à la technologie.', 'Chef de projet IT depuis plus de 20 ans (jeu vidéo, GED/OCR, ingénierie événementielle), je pilote les projets du cadrage au déploiement avec une bonne facilité de compréhension technique et fonctionnelle des sujets.', 'Nantes', 'antogouvrillon@gmail.com', 'https://linkedin.com/in/anthonygouvrillon', '', '2026-11-09T10:16:30.213000', '2026-11-09T12:10:20.581000');
